import { Router } from "express";
import { asyncHandler } from "../../../shared/http/async-handler.js";
import { BeneficiarioController, beneficiarioOcrUploadMiddleware } from "../controllers/beneficiario.controller.js";
import { ensureAuthenticated, ensurePermissions } from "../../auth/middlewares/auth.middleware.js";
const controller = new BeneficiarioController();
export const beneficiarioRoutes = Router();
const permissoesLeitura = ["ADMINISTRADOR", "OPERADOR", "LEITURA_APENAS"];
const permissoesEscrita = ["ADMINISTRADOR", "OPERADOR"];
const permissaoExclusao = ["ADMINISTRADOR"];
beneficiarioRoutes.get("/", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listar.bind(controller)));
beneficiarioRoutes.get("/proximo-codigo", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.obterProximoCodigo.bind(controller)));
beneficiarioRoutes.get("/sugestao-endereco", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.obterSugestaoEndereco.bind(controller)));
beneficiarioRoutes.get("/pendencias", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarPendencias.bind(controller)));
beneficiarioRoutes.post("/duplicidades/analisar", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.analisarDuplicidade.bind(controller)));
beneficiarioRoutes.post("/rapido", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criarRapido.bind(controller)));
beneficiarioRoutes.post("/ocr/cpf", ensureAuthenticated, ensurePermissions(permissoesEscrita), beneficiarioOcrUploadMiddleware, asyncHandler(controller.lerCpfPorOcr.bind(controller)));
beneficiarioRoutes.get("/:id/completude", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.obterCompletude.bind(controller)));
beneficiarioRoutes.post("/:id/completude/recalcular", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.recalcularCompletude.bind(controller)));
beneficiarioRoutes.get("/:id/consentimentos", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarConsentimentos.bind(controller)));
beneficiarioRoutes.post("/:id/consentimentos", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.registrarConsentimento.bind(controller)));
beneficiarioRoutes.get("/:id/auditoria", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.listarAuditoria.bind(controller)));
beneficiarioRoutes.get("/:id/familia-resumo", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.obterResumoFamilia.bind(controller)));
beneficiarioRoutes.get("/:id", ensureAuthenticated, ensurePermissions(permissoesLeitura), asyncHandler(controller.buscarPorId.bind(controller)));
beneficiarioRoutes.post("/", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.criar.bind(controller)));
beneficiarioRoutes.put("/:id", ensureAuthenticated, ensurePermissions(permissoesEscrita), asyncHandler(controller.atualizar.bind(controller)));
beneficiarioRoutes.delete("/:id", ensureAuthenticated, ensurePermissions(permissaoExclusao), asyncHandler(controller.remover.bind(controller)));
